<template>
  <section class="annotation-tools"><h3>{{ $t('expertWorkspace.annotations') }}</h3><p>{{ $t('expertWorkspace.savedNote') }}</p><p v-if="error" role="alert">{{ error }}</p><div class="history-actions"><button type="button" :disabled="loading || busy" @click="$emit('refresh')">{{ $t('annotations.refresh') }}</button><small v-if="loading" role="status">{{ $t('annotations.working') }}</small></div><p v-if="!items.length && !loading" class="empty">{{ $t('expertWorkspace.annotationEmpty') }}</p><ol v-if="items.length"><li v-for="item in items" :key="annotationId(item)"><strong>{{ item.annotation?.label || item.row?.attachment?.filename }}</strong><small>{{ $t(inDraft(item) ? 'expertWorkspace.inDraft' : item.sent ? 'expertWorkspace.sent' : 'expertWorkspace.annotationSaved') }}</small><div><button type="button" :disabled="busy" @click="$emit('open', item)">{{ $t('expertWorkspace.openAnnotation') }}</button><button type="button" :disabled="!writable || busy || (!item.sent && inDraft(item))" @click="$emit('add', item.annotation ? item : item.row)">{{ $t(item.sent ? 'annotations.saveCopy' : 'expertWorkspace.addToDraft') }}</button></div></li></ol><button v-if="more" type="button" :disabled="loading || busy" @click="$emit('more')">{{ $t('annotations.more') }}</button></section>
</template>
<script>
export default { name:'ExpertAnnotationTools', props:{ items:{type:Array,default:()=>[]}, draftRows:{type:Array,default:()=>[]}, writable:Boolean, busy:Boolean, loading:Boolean, more:Boolean, error:{type:String,default:''} }, emits:['add','open','refresh','more'], methods:{ annotationId(item){ return item.annotation?.id || item.row?.attachment?.metadata?.annotation_id || item.row?.attachment?.id; }, inDraft(item){ const id=item.annotation?.render_attachment_id || item.row?.attachment?.id; return this.draftRows.some(row=>String(row.attachment?.id)===String(id)); } } };
</script>
<style scoped>
.history-actions { display:flex; gap:8px; align-items:center; margin:8px 0; }h3 { font-size:15px; margin:0 0 10px; }p,small { font-size:12px; color:var(--el-text-color-secondary, #909399); line-height:1.7; }ol { list-style:none; padding:0; margin:0; }li { border:1px solid var(--admin-border, #e5e9f0); border-radius:8px; padding:10px; margin:10px 0; }strong { display:block; font-size:12px; overflow-wrap:anywhere; }small { display:block; margin:5px 0; }li>div { display:flex; flex-wrap:wrap; gap:5px; }button { font:inherit; font-size:11px; padding:7px; color:var(--el-color-primary, #409eff); background:white; border:1px solid var(--admin-border, #e5e9f0); border-radius:5px; cursor:pointer; }button:disabled { opacity:.45; cursor:not-allowed; }button:focus-visible { outline:3px solid var(--el-color-primary-light-3, #79bbff); outline-offset:2px; }.empty { padding:10px 0; }
</style>
